scaled = pd.DataFrame(StandardScaler().fit_transform(df), columns=df.columns)

fig, (left, right) = plt.subplots(1, 2, figsize=(9, 3.3))
left.boxplot([df["salary"], df["age"]], tick_labels=["salary", "age"])
left.set_title("Raw: salary dwarfs age")
right.boxplot([scaled["salary"], scaled["age"]], tick_labels=["salary", "age"])
right.axhline(0, color="#0a7d4f", lw=1, ls="--")
right.set_title("Standard scaled: same footing")
fig.tight_layout()
plt.show()</code></pre>
<!-- /wp:code -->

<!-- wp:shortcode -->
[vs_figure file="eda-scaling-before-after.svg" alt="Two box plots: on the raw scale age is squashed flat next to salary; after standard scaling both boxes are centred on zero with similar size"]
<!-- /wp:shortcode -->

<!-- wp:paragraph -->
<p>Scaling changes the units, not the shape of the data. Tree models don\'t need it; distance and gradient-based models do.</p>
